#!/usr/bin/env node
/**
 * Build the interface language files from the translation sources.
 *
 *   data/i18n/strings/*.txt        hand-kept: English ¦ Irish ¦ Ulster-Scots, one string a line
 *   data/i18n/map-names.overlay.json   generated by build-map-name-overlay.mjs (map names)
 *        |
 *        v
 *   assets/i18n/en.json, ga.json, sco.json     key -> string, what the runtime reads
 *   assets/i18n/names.ga.json, names.sco.json  English map/catalogue name -> translation
 *   data/i18n/review/*.tsv                     the lists a fluent speaker reviews
 *
 * SOURCE FORMAT (data/i18n/strings/<surface>.txt)
 *
 *   # a comment
 *   Add to map ¦ Cuir leis an léarscáil ¦ Pit on the map
 *   @chrome.language Language ¦ Teanga ¦ Leid
 *   Show all {n} maps ¦ Taispeáin na {n} léarscáil ar fad ¦
 *   Long paragraph of English ¦ ¦                  <- listed as untranslated in both
 *
 * The key is "<surface>.<slug of the English>" unless an @key is given. An empty column is a
 * missing translation: the runtime falls back to English and the review list says so. {name}
 * placeholders must appear in every translation that has the English one.
 *
 * Every translation is a DRAFT (each output file carries "_status": "draft") until a fluent
 * speaker has reviewed it; data/i18n/README.md explains how to record a
 * review.
 *
 * USAGE
 *   node scripts/i18n/build-i18n.mjs          write the outputs
 *   node scripts/i18n/build-i18n.mjs --check  fail if an output is out of date or a source line
 *                                             is malformed
 */
import { createHash } from 'node:crypto';
import { existsSync, mkdirSync, readFileSync, readdirSync, writeFileSync } from 'node:fs';
import path from 'node:path';

const CHECK = process.argv.includes('--check');
const SRC_DIR = 'data/i18n/strings';
const OUT_DIR = 'assets/i18n';
const REVIEW_DIR = 'data/i18n/review';
const OVERLAY = 'data/i18n/map-names.overlay.json';
const LANGS = ['ga', 'sco'];
const SEP = '¦';

const META = {
  en: { language: 'English', bcp47: 'en-GB', role: 'source and fallback for every key' },
  ga: {
    language: 'Irish (Gaeilge)',
    bcp47: 'ga',
    standard: 'An Caighdeán Oifigiúil',
    terminology: 'téarma.ie (National Terminology Database for Irish, © Foras na Gaeilge) for administrative, electoral and computing terms; individual terms used, the database is not reproduced',
    reviewedBy: null
  },
  sco: {
    language: 'Ulster-Scots (Ulstèr-Scotch)',
    bcp47: 'sco-ulster',
    standard: 'none settled; conservative forms only, from published official usage where found (NI Assembly Ulster-Scots leaflet, NISRA census leaflet, Ulster-Scots Agency / Tha Boord o Ulstèr-Scotch); otherwise English is kept',
    reviewedBy: null
  }
};

function slug(text) {
  return text.toLowerCase()
    .normalize('NFKD').replace(/[̀-ͯ]/g, '')
    .replace(/\{([a-z0-9_]+)\}/gi, '$1')
    .replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '')
    .slice(0, 56) || 'x';
}

const placeholders = (s) => [...String(s).matchAll(/\{([a-zA-Z0-9_]+)\}/g)].map((m) => m[1]).sort().join(',');

function readSources() {
  const problems = [];
  const entries = [];
  const files = existsSync(SRC_DIR) ? readdirSync(SRC_DIR).filter((f) => f.endsWith('.txt')).sort() : [];
  for (const file of files) {
    const surface = path.basename(file, '.txt');
    const lines = readFileSync(path.join(SRC_DIR, file), 'utf8').replace(/\r\n/g, '\n').split('\n');
    lines.forEach((raw, i) => {
      const line = raw.trim();
      if (!line || line.startsWith('#')) return;
      const where = `${SRC_DIR}/${file}:${i + 1}`;
      let key = null;
      let body = line;
      const km = /^@([A-Za-z0-9_.-]+)\s+(.*)$/.exec(line);
      if (km) { key = km[1]; body = km[2]; }
      const cols = body.split(SEP).map((c) => c.trim());
      if (cols.length !== 3) { problems.push(`${where}: expected 3 columns separated by ${SEP}, found ${cols.length}`); return; }
      const [en, ga, sco] = cols;
      if (!en) { problems.push(`${where}: empty English`); return; }
      for (const [lang, text] of [['ga', ga], ['sco', sco]]) {
        if (text && placeholders(text) !== placeholders(en)) problems.push(`${where}: ${lang} placeholders {${placeholders(text)}} differ from English {${placeholders(en)}}`);
      }
      entries.push({ key: key || `${surface}.${slug(en)}`, explicit: Boolean(key), surface, en, ga, sco, where });
    });
  }
  // Keys must be unique; an auto key that collides with a different English gets a hash suffix.
  const seen = new Map();
  for (const e of entries) {
    const prior = seen.get(e.key);
    if (prior && prior.en === e.en) {
      if ((e.ga && prior.ga && e.ga !== prior.ga) || (e.sco && prior.sco && e.sco !== prior.sco)) {
        problems.push(`${e.where}: "${e.en}" is translated differently at ${prior.where}`);
      }
      e.duplicate = true;
      continue;
    }
    if (prior) {
      if (e.explicit) { problems.push(`${e.where}: key ${e.key} already used at ${prior.where}`); continue; }
      e.key = `${e.key}_${createHash('sha1').update(e.en).digest('hex').slice(0, 6)}`;
    }
    seen.set(e.key, e);
  }
  // The same English under two keys must not be translated two ways: the runtime matches
  // rendered text by its English wording and can only pick one.
  const byEnglish = new Map();
  for (const e of entries) {
    // units.txt holds the form a noun takes after a numeral ("32 contae"), deliberately
    // different from the heading form ("Contaetha"); the runtime keeps them apart.
    if (e.duplicate || e.surface === 'units' || e.key.startsWith('months.')) continue;
    const prior = byEnglish.get(e.en);
    if (prior) {
      for (const lang of LANGS) {
        if (e[lang] && prior[lang] && e[lang] !== prior[lang]) problems.push(`${e.where}: "${e.en}" (${lang}) differs from ${prior.where}: "${e[lang]}" vs "${prior[lang]}"`);
      }
    } else byEnglish.set(e.en, e);
  }
  return { entries: entries.filter((e) => !e.duplicate), problems };
}

function stable(obj) {
  return `${JSON.stringify(obj, null, 1)}\n`;
}

function build() {
  const { entries, problems } = readSources();
  const outputs = new Map();
  const strings = { en: {}, ga: {}, sco: {} };
  for (const e of entries) {
    strings.en[e.key] = e.en;
    if (e.ga) strings.ga[e.key] = e.ga;
    if (e.sco) strings.sco[e.key] = e.sco;
  }
  const total = entries.length;
  outputs.set(`${OUT_DIR}/en.json`, stable({ _status: 'source', _meta: { ...META.en, keys: total }, strings: strings.en }));
  for (const lang of LANGS) {
    outputs.set(`${OUT_DIR}/${lang}.json`, stable({
      _status: 'draft',
      _meta: { ...META[lang], keys: Object.keys(strings[lang]).length, of: total, note: 'DRAFT: not reviewed by a fluent speaker. Not for publication until reviewed (data/i18n/README.md).' },
      strings: strings[lang]
    }));
  }

  // Names: map names from the generated overlay (complete translations only).
  const overlay = existsSync(OVERLAY) ? JSON.parse(readFileSync(OVERLAY, 'utf8')) : { maps: {} };
  for (const lang of LANGS) {
    const names = {};
    for (const rec of Object.values(overlay.maps || {})) {
      const value = rec[lang];
      if (value && rec.en && value !== rec.en) names[rec.en] = value;
    }
    for (const rec of Object.values(overlay.extraNames || {})) {
      if (rec[lang] && rec.en && rec[lang] !== rec.en) names[rec.en] = rec[lang];
    }
    outputs.set(`${OUT_DIR}/names.${lang}.json`, stable({
      _status: 'draft',
      _meta: { note: 'English map / catalogue name -> translation. Generated from data/i18n/map-names.overlay.json by scripts/i18n/build-i18n.mjs; DRAFT, not reviewed.', count: Object.keys(names).length },
      names: Object.fromEntries(Object.entries(names).sort(([a], [b]) => a.localeCompare(b)))
    }));
  }

  // Review lists: every translated string (for review) and every untranslated one.
  const tsv = (rows) => rows.map((r) => r.map((c) => String(c ?? '').replace(/[\t\n]/g, ' ')).join('\t')).join('\n') + '\n';
  for (const lang of LANGS) {
    const rows = [['key', 'surface', 'english', `draft_${lang}`, 'status']];
    for (const e of entries) rows.push([e.key, e.surface, e.en, e[lang], e[lang] ? 'draft - needs review' : 'UNTRANSLATED - English shown']);
    outputs.set(`${REVIEW_DIR}/strings-${lang}.tsv`, tsv(rows));
  }
  const nameRows = [['map_id', 'english', 'draft_ga', 'draft_sco', 'status', 'description']];
  for (const [id, rec] of Object.entries(overlay.maps || {}).sort(([a], [b]) => a.localeCompare(b))) {
    nameRows.push([id, rec.en, rec.ga || '', rec.sco || '', rec.ga ? 'draft - needs review' : `UNTRANSLATED${rec.missing ? ` (no glossary entry: ${rec.missing.join('; ')})` : ''}`, rec.descriptionUntranslated ? 'description in English only' : '']);
  }
  outputs.set(`${REVIEW_DIR}/map-names.tsv`, tsv(nameRows));

  const summary = {
    _note: 'Generated by scripts/i18n/build-i18n.mjs. Coverage of the draft translations.',
    interfaceStrings: { total, ga: Object.keys(strings.ga).length, sco: Object.keys(strings.sco).length },
    bySurface: {},
    mapNames: overlay.summary || null
  };
  for (const e of entries) {
    const s = (summary.bySurface[e.surface] ||= { total: 0, ga: 0, sco: 0 });
    s.total += 1;
    if (e.ga) s.ga += 1;
    if (e.sco) s.sco += 1;
  }
  outputs.set(`${REVIEW_DIR}/coverage.json`, stable(summary));
  return { outputs, problems, summary };
}

const { outputs, problems, summary } = build();
if (problems.length) {
  console.error(problems.map((p) => `FAIL: ${p}`).join('\n'));
  process.exit(1);
}
const stale = [];
for (const [file, content] of outputs) {
  const current = existsSync(file) ? readFileSync(file, 'utf8').replace(/\r\n/g, '\n') : null;
  if (current === content) continue;
  if (CHECK) stale.push(file);
  else {
    mkdirSync(path.dirname(file), { recursive: true });
    writeFileSync(file, content);
  }
}
if (CHECK && stale.length) {
  console.error(`FAIL: out of date (run node scripts/i18n/build-i18n.mjs): ${stale.join(', ')}`);
  process.exit(1);
}
const s = summary.interfaceStrings;
console.log(`i18n: ${s.total} interface strings; Irish ${s.ga}, Ulster-Scots ${s.sco}${CHECK ? ' (up to date)' : ''}.`);
